----------------
--- MONITORS ---
----------------

-- See https://wiki.hypr.land/Configuring/Monitors/
hl.monitor({
    output   = "",
    mode     = "preferred",
    position = "auto",
    scale    = 1.0,
})


-------------------
--- MY PROGRAMS ---
-------------------

-- See https://wiki.hypr.land/Configuring/Keywords/

-- Set programs that you use
local terminal      = "kitty"
local fileManager   = "thunar"
local menu          = "wofi --show drun"
local browser       = "firefox"
local btop          = "~/.config/scripts/bin/btopInit.sh"
local scriptRunner  = "~/.config/scripts/bin/runner.sh"
local screenCapture = "flameshot gui"
-----------------
--- AUTOSTART ---
-----------------

-- Autostart necessary processes (like notifications daemons, status bars, etc.)
-- Or execute your favorite apps at launch like this:

hl.on("hyprland.start", function()
    -- exec-once = $terminal
    hl.exec_cmd("hypridle")
    hl.exec_cmd("waypaper --restore")
    hl.exec_cmd("mako &")
    hl.exec_cmd("/usr/lib/polkit-gnome/polkit-gnome-authentication-agent-1")
    hl.exec_cmd("udiskie &") --automounter for usb/devices and that bullshit
    -- only if using tray
    hl.exec_cmd("nm-applet &")
    -- exec-once = blueman-applet &

    hl.exec_cmd("~/.config/scripts/bin/reload.sh")
end)


-----------------------------
--- ENVIRONMENT VARIABLES ---
-----------------------------

-- See https://wiki.hypr.land/Configuring/Environment-variables/

hl.env("XCURSOR_SIZE", "21")
hl.env("HYPRCURSOR_SIZE", "21")


