    name = "epic-mouse-v1",
    sensitivity = -0.5,
})


-------------------
--- KEYBINDINGS ---
-------------------

-- See https://wiki.hypr.land/Configuring/Keywords/
local mainMod = "SUPER" -- Sets "Windows" key as main modifier

-- Example binds, see https://wiki.hypr.land/Configuring/Binds/ for more
hl.bind(mainMod .. " + RETURN", hl.dsp.exec_cmd(terminal))
hl.bind(mainMod .. " + Q", hl.dsp.window.close())
hl.bind(mainMod .. " + M", hl.dsp.exit())
hl.bind(mainMod .. " + T", hl.dsp.exec_cmd(fileManager))
hl.bind(mainMod .. " + V", hl.dsp.window.float({ action = "toggle" }))
-- bind = $mainMod, R, exec, $menu
-- bind = $mainMod, P, pseudo, # dwindle
-- bind = $mainMod, J, togglesplit, # dwindle
hl.bind(mainMod .. " + KP_Add", hl.dsp.exec_cmd("~/.config/scripts/bin/hypr-scale + || hyprctl reload")) -- adds to scrsh -c 'wallust run "$($getCurrentWallpaper)" && bash ~/.config/wallust/templates/fastfetch-colors.sh'een scale
hl.bind(mainMod .. " + KP_Subtract", hl.dsp.exec_cmd("~/.config/scripts/bin/hypr-scale - || hyprctl reload")) -- lowers screen scale
hl.bind(mainMod .. " + W", hl.dsp.exec_cmd("~/.config/scripts/bin/reload.sh"))
hl.bind(mainMod .. " + P", hl.dsp.exec_cmd("sh -c 'waypaper --folder ~/.config/wallpapers'")) -- opens wallpaper gui.
hl.bind(mainMod .. " + E", hl.dsp.exec_cmd("sh -c 'rofi -show run'"))
hl.bind(mainMod .. " + X", hl.dsp.exec_cmd("sh -c " .. scriptRunner))

--Requires Hyprlock (lockscreen)
hl.bind(mainMod .. " + L", hl.dsp.exec_cmd("sh -c 'hyprlock -c ~/.config/hypr/hyprlock.conf'"))

-- Move focus with mainMod + arrow keys
hl.bind(mainMod .. " + left", hl.dsp.focus({ direction = "left" }))
hl.bind(mainMod .. " + right", hl.dsp.focus({ direction = "right" }))
hl.bind(mainMod .. " + up", hl.dsp.focus({ direction = "up" }))
hl.bind(mainMod .. " + down", hl.dsp.focus({ direction = "down" }))
hl.bind(mainMod .. " + B", hl.dsp.exec_cmd("sh -c " .. btop))

-- Switch workspaces with mainMod + [0-9]
hl.bind(mainMod .. " + 1", hl.dsp.focus({ workspace = 1 }))
hl.bind(mainMod .. " + 2", hl.dsp.focus({ workspace = 2 }))
hl.bind(mainMod .. " + 3", hl.dsp.focus({ workspace = 3 }))
hl.bind(mainMod .. " + 4", hl.dsp.focus({ workspace = 4 }))
hl.bind(mainMod .. " + 5", hl.dsp.focus({ workspace = 5 }))
hl.bind(mainMod .. " + 6", hl.dsp.focus({ workspace = 6 }))
hl.bind(mainMod .. " + 7", hl.dsp.focus({ workspace = 7 }))
hl.bind(mainMod .. " + 8", hl.dsp.focus({ workspace = 8 }))
hl.bind(mainMod .. " + 9", hl.dsp.focus({ workspace = 9 }))
hl.bind(mainMod .. " + 0", hl.dsp.focus({ workspace = 10 }))

-- Move active window to a workspace with mainMod + SHIFT + [0-9]
hl.bind(mainMod .. " + SHIFT + 1", hl.dsp.window.move({ workspace = 1 }))
hl.bind(mainMod .. " + SHIFT + 2", hl.dsp.window.move({ workspace = 2 }))
hl.bind(mainMod .. " + SHIFT + 3", hl.dsp.window.move({ workspace = 3 }))
hl.bind(mainMod .. " + SHIFT + 4", hl.dsp.window.move({ workspace = 4 }))
hl.bind(mainMod .. " + SHIFT + 5", hl.dsp.window.move({ workspace = 5 }))
hl.bind(mainMod .. " + SHIFT + 6", hl.dsp.window.move({ workspace = 6 }))
hl.bind(mainMod .. " + SHIFT + 7", hl.dsp.window.move({ workspace = 7 }))
hl.bind(mainMod .. " + SHIFT + 8", hl.dsp.window.move({ workspace = 8 }))
hl.bind(mainMod .. " + SHIFT + 9", hl.dsp.window.move({ workspace = 9 }))
hl.bind(mainMod .. " + SHIFT + 0", hl.dsp.window.move({ workspace = 10 }))

-- Go fullscreen on active window
hl.bind(mainMod .. " + F", hl.dsp.window.fullscreen({ mode = "fullscreen" }))

-- Switch to the most recently used workspace
hl.bind(mainMod .. " + TAB", hl.dsp.focus({ workspace = "previous" }))
-- Example special workspace (scratchpad)
-- bind = $mainMod, S, togglespecialworkspace, magic
-- bind = $mainMod SHIFT, S, movetoworkspace, special:magic
hl.bind(mainMod .. " + S", hl.dsp.exec_cmd(browser))


-- Scroll through existing workspaces with mainMod + scroll
hl.bind(mainMod .. " + mouse_down", hl.dsp.focus({ workspace = "e+1" }))
hl.bind(mainMod .. " + mouse_up", hl.dsp.focus({ workspace = "e-1" }))

-- Move/resize windows with mainMod + LMB/RMB and dragging
hl.bind(mainMod .. " + mouse:272", hl.dsp.window.drag(), { mouse = true })
hl.bind(mainMod .. " + mouse:273", hl.dsp.window.resize(), { mouse = true })

-- Audio keys
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("pactl set-sink-volume 0 +5%"), { locked = true })
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("pactl set-sink-volume 0 -5%"), { locked = true })
hl.bind("XF86AudioMute", hl.dsp.exec_cmd("pactl set-sink-mute @DEFAULT_SINK@ toggle"), { locked = true })

-- Mic mute
hl.bind("XF86AudioMicMute", hl.dsp.exec_cmd("pactl set-source-mute @DEFAULT_SOURCE@ toggle"), { locked = true })
hl.bind("XF86MonBrightnessUp", hl.dsp.exec_cmd("brightnessctl -e4 -n2 set 5%+"), { locked = true, repeating = true })
hl.bind("XF86MonBrightnessDown", hl.dsp.exec_cmd("brightnessctl -e4 -n2 set 5%-"), { locked = true, repeating = true })

-- Requires playerctl
hl.bind("XF86AudioNext", hl.dsp.exec_cmd("playerctl next"), { locked = true })
hl.bind("XF86AudioPause", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPlay", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPrev", hl.dsp.exec_cmd("playerctl previous"), { locked = true })

-- Screencapture tool
hl.bind(mainMod .. " + Print", hl.dsp.exec_cmd(screenCapture), { locked = true })

------------------------------
--- WINDOWS AND WORKSPACES ---
------------------------------

-- See https://wiki.hypr.land/Configuring/Window-Rules/ for more
-- See https://wiki.hypr.land/Configuring/Workspace-Rules/ for workspace rules

-- Float all terminal windows and set default size
-- windowrulev2 = float,class:kitty
-- windowrulev2 = floating_size:500x500,class:kitty,centered

-- Alacritty rules

hl.window_rule({
    name = "terminal-float",
    match = { initial_class = terminal },
    fullscreen = false,
    float = true,
    size = "900 600",
    move = "(cursor_x-450) (cursor_y-275)",
})

hl.window_rule({
    name = "browser-tile",
    match = { initial_class = browser },
    float = false,
})
--Discord rules
hl.window_rule({
    name = "discord-float",
    match = { initial_class = "Discord" },
    float = true,
    size = "1000 800",
    center = true,
})

hl.window_rule({
    name = "network-manager-float",
    match = { initial_class = "com.network.manager" },
    float = true,
    size = "500 400",
    center = true,
})
hl.window_rule({
    name = "pavucontrol-float",
    match = { initial_class = "org.pulseaudio.pavucontrol" },
    float = true,
    size = "500 400",
    center = true,
})
hl.window_rule({
    name = "blueman-manager-float",
    match = { initial_class = "blueman-manager" },
    float = true,
    size = "500 400",
    center = true,
})
-- Ignore maximize requests from apps. You'll probably like this.
-- windowrule = suppressevent maximize, class:.*

-- Fix some dragging issues with XWayland
--windowrule = nofocus,class:^$,title:^$,xwayland:1,floating:1,fullscreen:0,pinned:1

hl.on("hyprland.start", function()
    hl.exec_cmd('gsettings set org.gnome.desktop.interface gtk-theme "Default"')
end)